  var AYAR_ANAHTAR = "__teknikPanelAyarlar";

  function ayarOku() {
    try { return JSON.parse(localStorage.getItem(AYAR_ANAHTAR) || "null"); } catch (e) { return null; }
  }

  function ayarGecerli(a) {
    return a && typeof a === "object" && a.paylasan && typeof a.paylasan === "object" &&
      Array.isArray(a.personel) && Array.isArray(a.firmalar);
  }

  function ayarKutusu(mesaj) {
    var eski = document.getElementById("__tpAyar");
    if (eski) eski.remove();
    var mevcut = ayarOku();
    var k = document.createElement("div");
    k.id = "__tpAyar";
    k.style.cssText = "position:fixed;top:16px;right:16px;z-index:2147483647;background:#fff;border:2px solid #1F4E78;" +
      "border-radius:8px;padding:14px 18px;font:14px Calibri,Arial,sans-serif;color:#111;box-shadow:0 4px 18px rgba(0,0,0,.25);" +
      "width:min(520px, calc(100vw - 32px));box-sizing:border-box;line-height:1.45";
    k.innerHTML =
      '<div style="font-weight:bold;color:#1F4E78;font-size:16px;margin-bottom:6px">TEKNİK PANEL – Ayarlar</div>' +
      '<div style="margin-bottom:8px">' + (mesaj || "") + "</div>" +
      '<textarea id="__tpAyarMetin" style="width:100%;height:140px;box-sizing:border-box;font:12px monospace;padding:6px" placeholder="Ayar kodunu buraya yapıştır"></textarea>' +
      '<button id="__tpAyarKaydet" style="display:block;width:100%;margin-top:10px;padding:10px;border:0;border-radius:6px;background:#2E7D32;color:#fff;font:bold 15px Calibri,Arial,sans-serif;cursor:pointer">Kaydet</button>' +
      '<div style="text-align:right;margin-top:8px"><a href="#" id="__tpAyarKapat" style="color:#1F4E78">Kapat</a></div>';
    document.body.appendChild(k);
    if (mevcut) document.getElementById("__tpAyarMetin").value = JSON.stringify(mevcut, null, 1);
    document.getElementById("__tpAyarKapat").onclick = function () { k.remove(); return false; };
    document.getElementById("__tpAyarKaydet").onclick = function () {
      var a = null;
      try { a = JSON.parse(document.getElementById("__tpAyarMetin").value); } catch (e) {}
      if (!ayarGecerli(a)) { alert("Ayar kodu okunamadı. AYAR_KODU.txt dosyasının tamamını kopyalayıp yapıştırdığından emin ol."); return; }
      try { localStorage.setItem(AYAR_ANAHTAR, JSON.stringify(a)); } catch (e) { alert("Kaydedilemedi: " + e.message); return; }
      k.remove();
      alert("Ayarlar kaydedildi. TEKNİK PANEL yer imine tekrar tıkla.");
    };
  }

  var ayar = ayarOku();
  if (!ayarGecerli(ayar)) {
    ayarKutusu("İlk kurulum: Bilgisayarındaki <b>AYAR_KODU.txt</b> dosyasının içindekinin tamamını kopyalayıp aşağıya yapıştır, sonra Kaydet'e bas. Bunu bu bilgisayarda bir kez yapman yeterli.");
    return;
  }
